# review fixes, gl28d2, 2026-11-20 UTC: R captures only inside MGS2_GL_LIVE's window, FBCHK's answers naming neither buffer, GE2 A/B's
# set-up line by mode, comments); generated
# by gen/mkapply2.py from /home/claude/t27 -> /home/claude/t28b (gl28 as reviewed) -> /home/claude/t28 (+ MGS2_EYE, MGS2_GL_LIVE,
# MGS2_GL_FBCHK, MGS2_ME_PIC_GE2_AB, MGS2_GL_SHOT_FLIPWAIT in psp/xl_psp.c) and main's .gl27bak copies): recreates the final gl28 tree from
# a copy of the gl27 tree (cp -a /home/claude/t27 TREE first) with exact string replacements in two stages: stage 1 (TREE_MOD) gives the
# reviewed gl28 files (each checked against t28b's md5), stage 2 (TREE_MOD_D) applies the gl28d hunks to psp/xl_psp.c (checked against
# t28's md5).  Each old string must occur exactly once in the file as it stands at that step, or the script stops with
# "gl28_apply: MISS" and writes nothing.  New files (psp/xme_rest.S) must not exist yet.  A result that differs from its md5 stops the
# script too (nothing written) unless --no-md5.  With --main MAINCOPY it also makes main's gl28 changes in MAINCOPY (a copy of main as it
# was for gl27: scripts/psp.sh and tools/me_call_chk.py as their .gl27bak copies; tools/xme_rest_chk.py, cfg/mgs2_gl28.cfg (the gl28d
# cfg, 2026-11-20) and cfg/mgs2_gl28b.cfg (gl28's cfg before the update, 4b342ad4) new), saving each changed original as <file>.gl27bak first.
# Run with python3 -I.
import sys, os, hashlib
args = sys.argv[1:]
nomd5 = '--no-md5' in args; args = [a for a in args if a != '--no-md5']
main = None
if '--main' in args:
    k = args.index('--main'); main = args[k + 1]; del args[k:k + 2]
if len(args) != 1:
    sys.exit('usage: python3 -I gl28_apply.py TREE [--main MAINCOPY] [--no-md5]')
tree = args[0]
def md5(s): return hashlib.md5(s.encode()).hexdigest()
plan = []   # (path, text, backup_path or None, must_not_exist)
def fail(m):
    print('gl28_apply: ' + m + '; nothing written'); sys.exit(1)
def mod(root, rel, hs, want):
    p = os.path.join(root, rel)
    if not os.path.isfile(p): fail('MISS: no file ' + p)
    s = open(p).read()
    for i, (old, new) in enumerate(hs):
        n = s.count(old)
        if n != 1: fail('MISS: %s hunk %d: the old string occurs %d times (want 1); it begins %r' % (p, i + 1, n, old[:120]))
        s = s.replace(old, new)
    if md5(s) != want and not nomd5: fail('%s: the result md5 %s is not gl28\'s %s' % (p, md5(s), want))
    return p, s
def mod_s(p, s, hs, want):   # gl28d: stage 2 on the text stage 1 made
    for i, (old, new) in enumerate(hs):
        n = s.count(old)
        if n != 1: fail('MISS: %s gl28d hunk %d: the old string occurs %d times (want 1); it begins %r' % (p, i + 1, n, old[:120]))
        s = s.replace(old, new)
    if md5(s) != want and not nomd5: fail('%s: the result md5 %s is not gl28d\'s %s' % (p, md5(s), want))
    return s
def new(root, rel, text, want):
    p = os.path.join(root, rel)
    if os.path.exists(p): fail(p + ' exists already')
    if md5(text) != want: fail('internal: %s text md5' % rel)
    return p, text

