TREE_NEW = [
  ('psp/xme_rest.S', '1bcfc0484083d228b5e2685ab14a1f29', '/* xme_rest.S - gl28 (2026-11-19; MGS2_ME_REST, power_design.md section 5 "R1" with power_critique.md section B): the picture loop\'s\n   Media Engine rests in HALT through the main CPU\'s turns.  This file is v30me5\'s psp/me_rest.S (2026-10-26, mgs2/psp/me_rest.S; Ffm\n   chose "Build it" on the decision card of 2026-10-26 20:43; 76,548 rests and 0 lost wakes on Ffm\'s PSP in v30me5 run 2) with its\n   symbols renamed me_rest* -> xme_rest* and nothing else changed: the same instructions in the same order (tools/xme_rest_chk.py\n   compares them with v30me5\'s file by mnemonic and operand at every build).  The pattern is mcidclan\'s (psp-media-engine-custom-core\n   me-core-custom.c and me-soft-interrupt, MIT, credited in third_party/ps2rc/NOTICE.md and psp_harness.md).\n   Register writes, the three of that card and no other: the ME\'s interrupt enable 0xBC300008 = 0x80000000 and flags 0xBC300000 =\n   0xFFFFFFFF once (xme_rest_init), the acknowledgement 0x80000000 to 0xBC300000 at each wake (xme_rest_vec), all on the ME; the main\n   CPU\'s interrupt to the ME 0xBC100044 = 1 is psp/me/hle_me_mgs2.c\'s hle_me_kick (kernel mode).  CP0 writes on the ME only: $25 (the\n   exception vector), $12 (Status: IE + IM2 only inside xme_rest\'s window), $14 (EPC in the handler).  HALT is .word 0x70000000.\n   Called only from psp/xme_me.c (xme_me_main: xme_rest_init when the main CPU asked for the rest at the start; xme_me_wait: xme_rest\n   in a main-CPU turn, after the handshake).  Words in the ME\'s boot memory after psp/me/hle_me_mgs2.c\'s progress words (0xBFC00400,\n   [0..11]; k_start clears [0..15] at every start), as v30me5:\n     [12] 0x430  the ME\'s interrupt flags 0xBC300000 as the handler found them at the last wake\n     [13] 0x434  the handler\'s wakes (counts on)\n     [14] 0x438  every flag bit the handler has found\n     [15] 0x43c  the EPC of the last wake (without its kseg0 bit)\n     [16] 0x440  the handler\'s save of $at\n     [17] 0x444  the exception vector before xme_rest_init (hle_me_mgs2.c\'s hle_me_fault, kseg0): every other exception goes there,\n                 so it is recorded and the ME halts for good, as before (the main CPU\'s take-back finds it: hle_me_exception) */\n    .set push\n    .set noreorder\n    .set noat\n    .text\n    .align 2\n\n/* void xme_rest_init(void): once, from xme_me_main (psp/xme_me.c; v30me5: from me_mix_work), before the first rest */\n    .globl xme_rest_init\n    .ent xme_rest_init\nxme_rest_init:\n    lui   $t2, 0xBFC0\n    mfc0  $t0, $25\n    sw    $t0, 0x444($t2)         /* [17] the vector the reset stub set */\n    sync\n    la    $t0, xme_rest_vec\n    lui   $t1, 0x8000\n    or    $t0, $t0, $t1           /* its kseg0 alias, as the stub gives hle_me_fault\'s */\n    mtc0  $t0, $25\n    sync\n    lui   $t1, 0xBC30\n    lui   $t0, 0x8000\n    sw    $t0, 8($t1)             /* 0xBC300008 = 0x80000000: the main CPU\'s interrupt enabled at the ME\'s interrupt controller */\n    sync\n    li    $t0, -1\n    sw    $t0, 0($t1)             /* 0xBC300000 = 0xFFFFFFFF: every flag cleared */\n    sync\n    jr    $ra\n    nop\n    .end xme_rest_init\n\n/* void xme_rest(void): Status + IE + IM2, HALT until the main CPU\'s interrupt, Status back as it was (IE off).  An interrupt taken\n   anywhere from xme_rest_begin to xme_rest_win_last (one already pending when IE goes on, or the one that ends the HALT) comes back to\n   xme_rest_end through xme_rest_vec, which keeps $t0 (it uses $k0, $k1 and $at, saved).  The handler\'s address is only 4-byte aligned,\n   as mcidclan\'s are (aligned(4) in me-core-custom.c and me-soft-interrupt): a 16-byte alignment here would move v30\'s code. */\n    .globl xme_rest\n    .globl xme_rest_begin\n    .globl xme_rest_halt\n    .globl xme_rest_end\n    .globl xme_rest_win_end\n    .globl xme_rest_win_last\n    .ent xme_rest\nxme_rest:\n    mfc0  $t0, $12\n    ori   $t1, $t0, 0x401\nxme_rest_begin:\n    mtc0  $t1, $12                /* interrupts on: IE + IM2 */\n    sync\n    nop\n    nop\nxme_rest_halt:\n    .word 0x70000000              /* HALT */\n    nop\n    nop\n    nop\nxme_rest_end:\n    mtc0  $t0, $12                /* interrupts off */\n    sync\n    nop\n    nop\nxme_rest_win_end:\n    jr    $ra\nxme_rest_win_last:\n    nop                           /* the jump\'s delay slot, the window\'s last word: on the Allegrex an exception there may give\n                                     this address as EPC (mcidclan\'s handler steps an EPC with Cause.BD back by 4) */\n    .end xme_rest\n\n/* the ME\'s exception vector from xme_rest_init on (CP0 $25, at its kseg0 alias) */\n    .align 2\n    .globl xme_rest_vec\n    .ent xme_rest_vec\nxme_rest_vec:\n    mfc0  $k0, $13                /* Cause */\n    andi  $k1, $k0, 0x7c          /* ExcCode: 0 = an interrupt */\n    bne   $k1, $zero, 9f\n    andi  $k1, $k0, 0x400         /* (delay slot) IP2: the interrupt from the main CPU */\n    beq   $k1, $zero, 9f\n    nop\n    mfc0  $k0, $14                /* EPC without its kseg0 bit: the link address */\n    sll   $k0, $k0, 1\n    srl   $k0, $k0, 1\n    la    $k1, xme_rest_begin\n    sltu  $k1, $k0, $k1\n    bne   $k1, $zero, 9f          /* before xme_rest\'s window */\n    nop\n    la    $k1, xme_rest_win_last\n    sltu  $k1, $k1, $k0\n    bne   $k1, $zero, 9f          /* after it */\n    nop\n    lui   $k1, 0xBFC0\n    sw    $k0, 0x43c($k1)         /* [15] EPC of this wake */\n    sw    $at, 0x440($k1)         /* [16] $at saved */\n    lui   $k0, 0xBC30\n    lw    $at, 0($k0)             /* the flags as found */\n    sw    $at, 0x430($k1)         /* [12] */\n    lw    $k0, 0x438($k1)\n    or    $k0, $k0, $at\n    sw    $k0, 0x438($k1)         /* [14] every bit found */\n    lw    $k0, 0x434($k1)\n    addiu $k0, $k0, 1\n    sw    $k0, 0x434($k1)         /* [13] wakes */\n    sync\n    lui   $k0, 0xBC30\n    lui   $k1, 0x8000\n    sw    $k1, 0($k0)             /* acknowledge: bit 31 of the flags written (mcidclan) */\n    sync\n    li    $at, 4096               /* then read until bit 31 is clear (mcidclan waits for the whole word: here bit 31, at most 4,096 reads) */\n1:  lw    $k1, 0($k0)\n    srl   $k1, $k1, 31\n    beq   $k1, $zero, 2f\n    addiu $at, $at, -1\n    bne   $at, $zero, 1b\n    nop\n2:  lui   $k1, 0xBFC0\n    lw    $at, 0x440($k1)         /* $at back */\n    mfc0  $k0, $12\n    ori   $k0, $k0, 1\n    xori  $k0, $k0, 1             /* Status: IE off (eret clears EXL) */\n    mtc0  $k0, $12\n    la    $k0, xme_rest_end\n    lui   $k1, 0x8000\n    or    $k0, $k0, $k1\n    mtc0  $k0, $14                /* back to xme_rest_end (kseg0) */\n    sync\n    nop\n    nop\n    eret\n    nop\n    nop\n    nop\n    nop\n    nop\n    nop\n    nop\n9:  lui   $k0, 0xBFC0\n    lw    $k0, 0x444($k0)         /* [17]: hle_me_fault records Cause / EPC / BadVAddr and halts */\n    jr    $k0\n    nop\n    .end xme_rest_vec\n    .set pop\n'),
]
MAIN_MOD = [
  ('scripts/psp.sh', '9ffdea86439aca7f675ed6f50f6b3bb2', [
    ('#   the same objects and the overlays w00a and w01a with -fprofile-use and GCDA=<folder>\'s *.gcda (copied in first; no file = no profile).\n#   ORDER=<folder>: its layout_elf.ld and layout_<stage>.ld copied in (psp/Makefile LAYOUT=1 links by them).  RELINK=<build folder>: no\n#   compile: that build\'s objects, genf.txt and gcda files copied in, then make links them (a new code order on the same objects).\n. "$(dirname "$0")/env.sh"\nP=${PSPD:-$B/psp}; SDK=$PSPDEV/psp/sdk\nTITLE=${TITLE:-MGS2 harness mainline gl19}\n',
     '#   the same objects and the overlays w00a and w01a with -fprofile-use and GCDA=<folder>\'s *.gcda (copied in first; no file = no profile).\n#   ORDER=<folder>: its layout_elf.ld and layout_<stage>.ld copied in (psp/Makefile LAYOUT=1 links by them).  RELINK=<build folder>: no\n#   compile: that build\'s objects, genf.txt and gcda files copied in, then make links them (a new code order on the same objects).\n# gl28 (nothing changes for a tree or a RELINK folder without it): xme_rest.o, the ME\'s rest (psp/xme_rest.S, MGS2_ME_REST), assembled\n#   when the tree has psp/xme_rest.S (RELINK: when the folder has xme_rest.o) and linked after the other objects; then ge_xme_me.o must\n#   name exactly xme_rest xme_rest_halt xme_rest_init xme_run (without it: xme_run, as before) and tools/xme_rest_chk.py must find\n#   xme_rest.o\'s instructions equal to v30me5\'s $MG/psp/me_rest.S renamed.  The gate now runs for RELINK too.\n. "$(dirname "$0")/env.sh"\nP=${PSPD:-$B/psp}; SDK=$PSPDEV/psp/sdk\nTITLE=${TITLE:-MGS2 harness mainline gl19}\n'),
    ('  o=$1; shift; s=$(date +%s)\n  { echo "cmd: $*"; eval "$@"; } > cc_$o.log 2>&1; r=$?; echo "$o rc $r $(( $(date +%s) - s )) s" >> cc_$o.log; tail -n 1 cc_$o.log; return $r\n}\ns0=$(date +%s)\nif [ -n "$RELINK" ]; then   # gl20: the objects of $RELINK as they are (no compile)\n  for o in $RELINK/*.o; do case $(basename $o) in ovl_hdr_*) ;; *) cp $o $P/ || exit 1 ;; esac; done   # (make builds the headers again)\n  cp $RELINK/genf.txt $RELINK/ge_xme_me.dis $RELINK/xme_me_chk.out $P/ || exit 1; echo "psp.sh: objects of $RELINK reused"\nelse\n# the G0 units (mkgen18c.sh without the profile)\ncc gen.o "psp-gcc $GENF $PEG -ffunction-sections \'-DGEN=\\"$G/wgh/gen_elf.h\\"\' -c $M/boot_g0/gen.c -o gen.o" &   # gl19: wg\'s with MGS2_HALF\'s two lines\n',
     '  o=$1; shift; s=$(date +%s)\n  { echo "cmd: $*"; eval "$@"; } > cc_$o.log 2>&1; r=$?; echo "$o rc $r $(( $(date +%s) - s )) s" >> cc_$o.log; tail -n 1 cc_$o.log; return $r\n}\nxme_gate() {   # gl28: the names ge_xme_me.o needs from outside itself (xme_run; with the rest object also its three), and xme_rest.o\'s check\n  XU="xme_run "; [ -f xme_rest.o ] && XU="xme_rest xme_rest_halt xme_rest_init xme_run "\n  [ "$(psp-nm -u ge_xme_me.o | awk \'{ print $2 }\' | tr \'\\n\' \' \')" = "$XU" ] || { echo "psp.sh: ge_xme_me.o names more than ${XU% }"; return 1; }\n  [ -f xme_rest.o ] || return 0\n  [ "$(psp-objdump -h xme_rest.o | awk \'$2 == ".text" { print $7 }\')" = "2**2" ] || { echo "psp.sh: xme_rest.o\'s .text is not 2**2 (v30me5\'s)"; return 1; }\n  python3 -I $M/tools/xme_rest_chk.py xme_rest.o $MG/psp/me_rest.S > xme_rest_chk.out 2>&1 || { echo "psp.sh: xme_rest_chk failed"; cat xme_rest_chk.out; return 1; }\n  tail -n 1 xme_rest_chk.out\n}\ns0=$(date +%s)\nif [ -n "$RELINK" ]; then   # gl20: the objects of $RELINK as they are (no compile)\n  for o in $RELINK/*.o; do case $(basename $o) in ovl_hdr_*) ;; *) cp $o $P/ || exit 1 ;; esac; done   # (make builds the headers again)\n  cp $RELINK/genf.txt $RELINK/ge_xme_me.dis $RELINK/xme_me_chk.out $P/ || exit 1; echo "psp.sh: objects of $RELINK reused"\n  xme_gate || exit 1   # gl28 (gl18me-gl27\'s RELINK objects pass it: ge_xme_me.o names xme_run only)\nelse\n# the G0 units (mkgen18c.sh without the profile)\ncc gen.o "psp-gcc $GENF $PEG -ffunction-sections \'-DGEN=\\"$G/wgh/gen_elf.h\\"\' -c $M/boot_g0/gen.c -o gen.o" &   # gl19: wg\'s with MGS2_HALF\'s two lines\n'),
    ('  cc ge_xme_me.o "psp-gcc $GF $MEF -fstack-usage -I$HP -c $M/psp/xme_me.c -o ge_xme_me.o" || exit 1\n  psp-objcopy --redefine-sym memcpy=me_memcpy --redefine-sym memset=me_memset --redefine-sym memcmp=me_memcmp ge_xme_me.o || exit 1\n  psp-objcopy --rename-section .bss=.me_bss --rename-section .data=.me_data ge_xme_me.o || exit 1\n  [ "$(psp-nm -u ge_xme_me.o | awk \'{ print $2 }\' | tr \'\\n\' \' \')" = "xme_run " ] || { echo "psp.sh: ge_xme_me.o names more than xme_run"; exit 1; }\n  psp-objdump -d ge_xme_me.o > ge_xme_me.dis && python3 -I $M/tools/xme_me_chk.py ge_xme_me.dis > xme_me_chk.out 2>&1 || { echo "psp.sh: xme_me_chk failed"; cat xme_me_chk.out; exit 1; }\n  cc hle_me.o "psp-gcc $BASEF -fno-merge-constants $MACHF -DHLE_PSP -DHLE_HAVE_AUDIO_MODEL -DME_REST -DME_SONY -DME_SONY_BOOT -DME_KADDR -I$SDK/include -I$HP -I$M/psp/me -c $M/psp/me/hle_me_mgs2.c -o hle_me.o" || exit 1\n  psp-objcopy --rename-section .text.hle_me_stub=.data.hle_me_stub,alloc,load,contents,data hle_me.o || exit 1\n',
     '  cc ge_xme_me.o "psp-gcc $GF $MEF -fstack-usage -I$HP -c $M/psp/xme_me.c -o ge_xme_me.o" || exit 1\n  psp-objcopy --redefine-sym memcpy=me_memcpy --redefine-sym memset=me_memset --redefine-sym memcmp=me_memcmp ge_xme_me.o || exit 1\n  psp-objcopy --rename-section .bss=.me_bss --rename-section .data=.me_data ge_xme_me.o || exit 1\n  if [ -f $M/psp/xme_rest.S ]; then cc xme_rest.o "psp-gcc -c $M/psp/xme_rest.S -o xme_rest.o" || exit 1; fi   # gl28 (as v30me5.sh\'s me_rest.o)\n  xme_gate || exit 1\n  psp-objdump -d ge_xme_me.o > ge_xme_me.dis && python3 -I $M/tools/xme_me_chk.py ge_xme_me.dis > xme_me_chk.out 2>&1 || { echo "psp.sh: xme_me_chk failed"; cat xme_me_chk.out; exit 1; }\n  cc hle_me.o "psp-gcc $BASEF -fno-merge-constants $MACHF -DHLE_PSP -DHLE_HAVE_AUDIO_MODEL -DME_REST -DME_SONY -DME_SONY_BOOT -DME_KADDR -I$SDK/include -I$HP -I$M/psp/me -c $M/psp/me/hle_me_mgs2.c -o hle_me.o" || exit 1\n  psp-objcopy --rename-section .text.hle_me_stub=.data.hle_me_stub,alloc,load,contents,data hle_me.o || exit 1\n'),
    ('# the rest and the link: psp/Makefile (rebuild_use.sh / mk_psp.sh\'s call; every object above kept with -o)\nOO=$(for o in *.o; do printf -- "-o %s " $o; done)\nXOBJS="xl_psp.o ge_xlive.o ge_xlate.o ge_gsfront.o ge_gsup2.o ge_texconv.o ge_texcache.o ge_gelive.o ge_gebatch.o ge_xconv.o ge_vu1conv.o ge_gelist.o ge_xlme.o ge_xme.o ge_xme_me.o ge_fxthin.o ge_me_rt.o gl1_glue.o v26me_bat.o exc3b.o exc3b_s.o ps2rc_kcall.o hle_me.o"\nXLIBS="-Wl,--wrap=host_vb_begin,--wrap=mgs2_exit,--wrap=sceKernelExitGame,--wrap=mgs2_main -lpspgu -lpspsystemctrl_user -Wl,-T,$M/psp/me_sec.ld"\nmake -f $M/psp/Makefile -j${J:-3} MG=$S W=$G/WP $MK OVL_SIZE=$OVLS LAYOUT=1 STAGES="$STAGES" PSP_EBOOT_TITLE="$TITLE" GENF="$GENF" RTX="$RTX" \\\n  XOBJS="$XOBJS" MAINX="-DMGS2_XL -DMGS2_GL -DPOOL_KB=512" XLIBS="$XLIBS" $OO > make.log 2>&1\n',
     '# the rest and the link: psp/Makefile (rebuild_use.sh / mk_psp.sh\'s call; every object above kept with -o)\nOO=$(for o in *.o; do printf -- "-o %s " $o; done)\nXOBJS="xl_psp.o ge_xlive.o ge_xlate.o ge_gsfront.o ge_gsup2.o ge_texconv.o ge_texcache.o ge_gelive.o ge_gebatch.o ge_xconv.o ge_vu1conv.o ge_gelist.o ge_xlme.o ge_xme.o ge_xme_me.o ge_fxthin.o ge_me_rt.o gl1_glue.o v26me_bat.o exc3b.o exc3b_s.o ps2rc_kcall.o hle_me.o"\n[ -f xme_rest.o ] && XOBJS="$XOBJS xme_rest.o"   # gl28: the ME\'s rest, last (absent: the link as before)\nXLIBS="-Wl,--wrap=host_vb_begin,--wrap=mgs2_exit,--wrap=sceKernelExitGame,--wrap=mgs2_main -lpspgu -lpspsystemctrl_user -Wl,-T,$M/psp/me_sec.ld"\nmake -f $M/psp/Makefile -j${J:-3} MG=$S W=$G/WP $MK OVL_SIZE=$OVLS LAYOUT=1 STAGES="$STAGES" PSP_EBOOT_TITLE="$TITLE" GENF="$GENF" RTX="$RTX" \\\n  XOBJS="$XOBJS" MAINX="-DMGS2_XL -DMGS2_GL -DPOOL_KB=512" XLIBS="$XLIBS" $OO > make.log 2>&1\n'),
  ]),
  ('tools/me_call_chk.py', '3f3f218e7e4e5bbd8e567add3c49159b', [
    ('#     the functions reached outside the ME-safe objects are listed (libc\'s memcpy and the like are expected).\n# Calls through other pointers are not followed (the ME\'s other pointers are set to ME-safe functions at the set-up and ran on the ME\n# from gl18me to gl19); that is the check\'s known gap.  Prints "me_call_chk: PASS" or "me_call_chk: FAIL (n)"; exit 0 on PASS.\nimport sys, os, re, subprocess\nB = sys.argv[1]\nBIN = \'/home/claude/pspsdk/pspdev/bin/\'\nME = [\'xlive\', \'xlate\', \'gsfront\', \'texconv\', \'texcache\', \'gelive\', \'gebatch\', \'xconv\', \'vu1conv\', \'gelist\', \'gsup2\', \'xlme\', \'xme\', \'me_rt\',\n      \'xme_me\']\nSRC = os.path.join(os.path.dirname(os.path.abspath(__file__)), \'..\', \'psp\', \'xl_psp.c\')\nelf = os.path.join(B, \'MGS2T.elf\')\ndis = subprocess.run([BIN + \'psp-objdump\', \'-d\', elf], capture_output=True, text=True, check=True).stdout\n',
     '#     the functions reached outside the ME-safe objects are listed (libc\'s memcpy and the like are expected).\n# Calls through other pointers are not followed (the ME\'s other pointers are set to ME-safe functions at the set-up and ran on the ME\n# from gl18me to gl19); that is the check\'s known gap.  Prints "me_call_chk: PASS" or "me_call_chk: FAIL (n)"; exit 0 on PASS.\n# gl28: psp/xme_rest.S (the ME\'s rest, MGS2_ME_REST) is ME code too.  An assembled object carries no FILE symbol, so its functions\n# are also roots by name when the ELF has them (xme_rest, xme_rest_init, xme_rest_vec and the labels inside xme_rest); an ELF without\n# them (gl27 and before) gets the same roots as before.\nimport sys, os, re, subprocess\nB = sys.argv[1]\nBIN = \'/home/claude/pspsdk/pspdev/bin/\'\nME = [\'xlive\', \'xlate\', \'gsfront\', \'texconv\', \'texcache\', \'gelive\', \'gebatch\', \'xconv\', \'vu1conv\', \'gelist\', \'gsup2\', \'xlme\', \'xme\', \'me_rt\',\n      \'xme_me\', \'xme_rest\']   # gl28: xme_rest (by name below as well)\nSRC = os.path.join(os.path.dirname(os.path.abspath(__file__)), \'..\', \'psp\', \'xl_psp.c\')\nelf = os.path.join(B, \'MGS2T.elf\')\ndis = subprocess.run([BIN + \'psp-objdump\', \'-d\', elf], capture_output=True, text=True, check=True).stdout\n'),
    ("    f = os.path.splitext(os.path.basename(files.get(name, '')))[0]\n    return f in ME or f.startswith('ge_') and f[3:] in ME\nroots = {n for n in fn if me_obj(n)} | set(sys.argv[2:])   # (more roots by name: the check's own test)\nsrc = open(SRC).read()\nfor field in ('clk_me', 'w_me'):\n    for m in re.finditer(r'->' + field + r'\\s*=\\s*(\\w+)', src): roots.add(m.group(1))\n",
     "    f = os.path.splitext(os.path.basename(files.get(name, '')))[0]\n    return f in ME or f.startswith('ge_') and f[3:] in ME\nroots = {n for n in fn if me_obj(n)} | set(sys.argv[2:])   # (more roots by name: the check's own test)\nroots |= {n for n in fn if re.match(r'xme_rest(_init|_vec|_begin|_halt|_end|_win_end|_win_last)?$', n)}   # gl28\nsrc = open(SRC).read()\nfor field in ('clk_me', 'w_me'):\n    for m in re.finditer(r'->' + field + r'\\s*=\\s*(\\w+)', src): roots.add(m.group(1))\n"),
    ("        outside.append(n)\nprint('me_call_chk: roots %d (ME-safe objects %d), reached %d, reached outside the ME-safe objects %d: %s'\n      % (len(roots), sum(1 for r in roots if me_obj(r)), len(seen), len(outside), ' '.join(outside[:40]) + (' ...' if len(outside) > 40 else '')))\nfor b in bad: print('me_call_chk: ' + b)\nprint('me_call_chk: PASS' if not bad else 'me_call_chk: FAIL (%d)' % len(bad))\nsys.exit(0 if not bad else 1)\n",
     "        outside.append(n)\nprint('me_call_chk: roots %d (ME-safe objects %d), reached %d, reached outside the ME-safe objects %d: %s'\n      % (len(roots), sum(1 for r in roots if me_obj(r)), len(seen), len(outside), ' '.join(outside[:40]) + (' ...' if len(outside) > 40 else '')))\nxr = sorted(n for n in seen if n.startswith('xme_rest'))   # gl28\nif xr: print('me_call_chk: the rest (psp/xme_rest.S) reached: %s' % ' '.join(xr))\nfor b in bad: print('me_call_chk: ' + b)\nprint('me_call_chk: PASS' if not bad else 'me_call_chk: FAIL (%d)' % len(bad))\nsys.exit(0 if not bad else 1)\n"),
  ]),
]
